<?php
namespace App\Domain\AI\Knowledge\Models;use App\Domain\AI\Agents\Data\AuthorizedAiLifecycleActor;use App\Domain\AI\Knowledge\Enums\KnowledgeVersionStatus;use App\Domain\AI\Support\Exceptions\AiImmutableAttributeException;use App\Domain\AI\Tenancy\AiTenantModel;use App\Models\User;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Support\Str;
final class KnowledgeSourceVersion extends AiTenantModel{protected$table='ai_knowledge_source_versions';protected$guarded=['*'];protected$casts=['version_number'=>'integer','status'=>KnowledgeVersionStatus::class,'content'=>'array','approved_at'=>'datetime'];public function getRouteKeyName():string{return'uuid';}public function isAiAppendOnly():bool{return true;}protected function immutableIdentityAttributes():array{return['uuid','knowledge_source_id','version_number','status','content','checksum','created_by_user_id','approved_by_user_id','approved_at'];}protected static function booted():void{parent::booted();static::creating(fn(self$m)=>$m->uuid??=(string)Str::uuid());static::saving(function(self$m){if($m->exists&&$m->getRawOriginal('status')!=='draft'&&$m->isDirty()&&!$m->allowsAiProtectedUpdate(array_keys($m->getDirty())))throw new AiImmutableAttributeException('Approved knowledge versions are immutable.');});}public function source():BelongsTo{return$this->belongsTo(KnowledgeSource::class,'knowledge_source_id');}public function creator():BelongsTo{return$this->belongsTo(User::class,'created_by_user_id');}public function approve(AuthorizedAiLifecycleActor$a):void{$this->assertLifecycleActor($a);$this->persistNamedLifecycle(['status','approved_by_user_id','approved_at'],function()use($a){$this->status=KnowledgeVersionStatus::Approved;$this->approved_by_user_id=$a->actorUserId;$this->approved_at=now();});}public function supersede(AuthorizedAiLifecycleActor$a):void{$this->assertLifecycleActor($a);$this->persistNamedLifecycle(['status'],fn()=>$this->status=KnowledgeVersionStatus::Superseded);}}
